"""Local FASTEXPR validation against synchronized metadata."""

from __future__ import annotations

from dataclasses import dataclass

from alpha_mining.domain.expression_ast import AstNode, ExpressionSyntaxError, parse_expression
from alpha_mining.offline.metadata import MetadataCache
from alpha_mining.parser.fastplus_gate import check_expression


@dataclass(frozen=True)
class ValidationIssue:
    code: str
    message: str


class LocalExpressionValidator:
    def __init__(self, metadata: MetadataCache) -> None:
        self.metadata = metadata

    def validate(self, expression: str) -> list[ValidationIssue]:
        fp = check_expression(expression)
        if fp.available and not fp.ok:
            return [ValidationIssue("FASTPLUS", fp.diagnostic)]
        try:
            root = parse_expression(expression)
        except ExpressionSyntaxError as exc:
            return [ValidationIssue("INVALID_SYNTAX", str(exc))]
        issues: list[ValidationIssue] = []

        def walk(node: AstNode, *, callee: bool = False) -> None:
            if node.kind == "call":
                operator = self.metadata.operators.get(node.value)
                if operator is None:
                    issues.append(ValidationIssue("UNKNOWN_OPERATOR", node.value))
                elif len(node.children) != operator.arity:
                    issues.append(
                        ValidationIssue(
                            "INVALID_ARITY",
                            f"{node.value} expects {operator.arity}, got {len(node.children)}",
                        )
                    )
                for child in node.children:
                    walk(child)
                return
            if node.kind == "ident" and not callee and node.value not in self.metadata.fields:
                issues.append(ValidationIssue("UNKNOWN_FIELD", node.value))
            for child in node.children:
                walk(child)

        walk(root)
        return issues
"""Shared candidate screening policy for production and offline pipelines.

Both CandidateGenerationService (production) and alpha_mining.offline.service
must route candidates through this module to ensure consistent rejection logic.
"""

from __future__ import annotations

import enum
from dataclasses import dataclass, field

from alpha_mining.domain.expression_ast import parse_expression, ExpressionSyntaxError
from alpha_mining.domain.expression_normalization import expression_identity


class RejectionReason(enum.Enum):
    NONE = "NONE"
    INVALID_SYNTAX = "INVALID_SYNTAX"
    UNKNOWN_OPERATOR = "UNKNOWN_OPERATOR"
    UNKNOWN_FIELD = "UNKNOWN_FIELD"
    GROUP_RANK_DISABLED = "GROUP_RANK_DISABLED"
    EXACT_HASH_EXISTS = "EXACT_HASH_EXISTS"
    FIELD_SKELETON_ROUND_LIMIT = "FIELD_SKELETON_ROUND_LIMIT"
    FIELD_SKELETON_ACTIVE_REQUEST = "FIELD_SKELETON_ACTIVE_REQUEST"
    FAMILY_COOLDOWN = "FAMILY_COOLDOWN"
    INVALID_IDENTITY = "INVALID_IDENTITY"


def _has_group_rank(expression: str) -> bool:
    try:
        from alpha_mining.domain.expression_ast import AstNode

        def _walk(node: AstNode) -> bool:
            if node.kind == "call" and str(node.value).startswith("group_"):
                return True
            return any(_walk(child) for child in node.children)

        return _walk(parse_expression(expression))
    except Exception:
        return False


@dataclass
class CandidateScreeningPolicy:
    """Stateless screening policy; callers maintain per-round seen sets."""

    group_rank_enabled: bool = False
    max_field_skeleton_per_round: int = 1

    def screen_expression(
        self,
        expression: str,
        *,
        round_seen_hashes: set[str],
        round_seen_skeletons: set[str],
    ) -> RejectionReason | None:
        """Return a RejectionReason if the expression should be rejected, else RejectionReason.NONE.

        Callers should treat both None and RejectionReason.NONE as "passed".
        """
        # Syntax check
        try:
            parse_expression(expression)
        except ExpressionSyntaxError:
            return RejectionReason.INVALID_SYNTAX
        except Exception:
            return RejectionReason.INVALID_SYNTAX

        # group_rank gate
        if not self.group_rank_enabled and _has_group_rank(expression):
            return RejectionReason.GROUP_RANK_DISABLED

        # Compute identity
        try:
            identity = expression_identity(expression)
        except Exception:
            return RejectionReason.INVALID_IDENTITY

        if not identity.exact_hash or not identity.field_skeleton:
            return RejectionReason.INVALID_IDENTITY

        # Exact hash deduplication (across history — callers must include historical hashes)
        if identity.exact_hash in round_seen_hashes:
            return RejectionReason.EXACT_HASH_EXISTS

        # Field skeleton per-round limit
        if identity.field_skeleton in round_seen_skeletons:
            return RejectionReason.FIELD_SKELETON_ROUND_LIMIT

        return RejectionReason.NONE
"""Read-only platform catalog synchronization used by the factory gate."""

from __future__ import annotations

import json
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Protocol


class CatalogClient(Protocol):
    def list_datasets(self, params: dict[str, object]) -> dict[str, Any]: ...
    def list_data_fields(self, params: dict[str, object]) -> dict[str, Any]: ...
    def list_operators(self, params: dict[str, object]) -> dict[str, Any]: ...


def _utc_timestamp() -> float:
    return datetime.now(timezone.utc).timestamp()


class PlatformCatalogSynchronizer:
    def __init__(self, cache_dir: str | Path, *, page_size: int = 50) -> None:
        self.cache_dir = Path(cache_dir)
        # The platform currently rejects catalog pagination above 50.
        self.page_size = max(1, min(50, int(page_size)))

    def _all_pages(self, fetch: Any, params: dict[str, object]) -> list[dict[str, Any]]:
        rows: list[dict[str, Any]] = []
        offset = 0
        expected: int | None = None
        while True:
            payload = fetch({**params, "limit": self.page_size, "offset": offset})
            if not isinstance(payload, dict) or not isinstance(payload.get("results"), list):
                raise ValueError("catalog response is not a paged object")
            count = int(payload.get("count") or 0)
            if expected is None:
                expected = count
            elif count != expected:
                raise ValueError("catalog count changed during pagination")
            batch = [item for item in payload["results"] if isinstance(item, dict)]
            rows.extend(batch)
            if len(rows) >= count:
                return rows[:count]
            if not batch:
                raise ValueError("catalog returned an empty incomplete page")
            offset += len(batch)

    def sync(self, client: CatalogClient, *, region: str, universe: str, delay: int) -> dict[str, int]:
        base = {"instrumentType": "EQUITY", "region": region, "universe": universe, "delay": int(delay)}
        datasets = self._all_pages(client.list_datasets, base)
        dataset_ids = [str(item.get("id") or "").strip() for item in datasets]
        dataset_ids = list(dict.fromkeys(item for item in dataset_ids if item))
        if not dataset_ids:
            raise ValueError("platform returned no dataset IDs")
        fields: list[dict[str, Any]] = []
        for dataset_id in dataset_ids:
            rows = self._all_pages(client.list_data_fields, {**base, "dataset.id": dataset_id})
            for row in rows:
                if str(row.get("id") or "").strip():
                    fields.append({**row, "_ds": dataset_id})
        if not fields:
            raise ValueError("platform returned no data fields")
        operators = self._all_pages(client.list_operators, base)
        names = [str(item.get("name") or item.get("id") or "").strip() for item in operators]
        names = list(dict.fromkeys(item for item in names if item))
        if not names:
            raise ValueError("platform returned no operator metadata")
        now = _utc_timestamp()
        payloads = {
            ".alpha_datasets_cache.json": {"cached_at": now, "dataset_ids": dataset_ids, "source": "platform_catalog"},
            ".alpha_datafields_cache.json": {"cached_at": now, "rows": fields, "source": "platform_catalog"},
            ".alpha_operators_cache.json": {"cached_at": now, "operators": names, "source": "platform_catalog"},
        }
        self.cache_dir.mkdir(parents=True, exist_ok=True)
        for filename, payload in payloads.items():
            target = self.cache_dir / filename
            temporary = target.with_name(target.name + ".tmp")
            temporary.write_text(json.dumps(payload, ensure_ascii=False, sort_keys=True), encoding="utf-8")
            temporary.replace(target)
        return {"datasets": len(dataset_ids), "data_fields": len(fields), "operators": len(names)}
"""The only production network gateway for simulate/check/PATCH/Submit."""

from __future__ import annotations

import time
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Callable
from urllib.parse import urljoin

import requests

from alpha_mining.factory.contracts import (
    SimulationCheckpoint,
    SimulationOutcomeUnknown,
)

from .client import BASE_URL, PlatformReadError, ReadOnlyPlatformClient
from .protocol import alpha_id_from_progress, extract_checks, extract_metrics


@dataclass
class PlatformGateway:
    state_path: str | Path = ".wq_auth_state.json"
    database: str | Path = "research_memory.sqlite"
    lock_path: str | Path = "worldquant_api.lock"
    timeout: float = 30.0
    min_interval: float = 2.0
    poll_interval: float = 2.0
    max_poll_seconds: float = 600.0
    sleeper: Callable[[float], None] = time.sleep

    def __post_init__(self) -> None:
        self.client = ReadOnlyPlatformClient(
            state_path=self.state_path,
            timeout=self.timeout,
            min_interval=self.min_interval,
            database=self.database,
            lock_path=self.lock_path,
            sleeper=self.sleeper,
        )

    def authenticate(self) -> None:
        self.client.authenticate()

    def fetch_alpha(self, alpha_id: str) -> dict[str, Any]:
        return self.client.fetch_alpha(alpha_id)

    def patch_alpha(self, alpha_id: str, payload: dict[str, Any]) -> dict[str, Any]:
        response = self.client.request(
            "PATCH",
            f"{BASE_URL}/alphas/{alpha_id}",
            json=payload,
            endpoint_class="description_patch",
            allow_server_retry=False,
        )
        if response.status_code not in {200, 201, 204}:
            raise PlatformReadError(f"description PATCH failed with HTTP {response.status_code}")
        return {"status_code": int(response.status_code)}

    def submit_alpha(self, alpha_id: str) -> dict[str, Any]:
        response = self.client.request(
            "POST",
            f"{BASE_URL}/alphas/{alpha_id}/submit",
            endpoint_class="submit",
            allow_server_retry=False,
        )
        if response.status_code not in {200, 201, 202}:
            raise PlatformReadError(f"submit failed with HTTP {response.status_code}")
        return {"status_code": int(response.status_code)}

    def simulate(
        self,
        *,
        expression: str,
        settings: dict[str, Any],
        alpha_type: str = "REGULAR",
        checkpoint: SimulationCheckpoint | None = None,
        checkpoint_sink: Callable[[SimulationCheckpoint], None] | None = None,
    ):
        from alpha_mining.factory.orchestrator import SimulationResult

        self.authenticate()
        resume = checkpoint or SimulationCheckpoint()
        alpha_id = str(resume.alpha_id or "").strip()
        location = str(resume.progress_location or "").strip()
        if alpha_id:
            detail = self.fetch_alpha(alpha_id)
            return SimulationResult(
                alpha_id=alpha_id,
                status="COMPLETE",
                metrics=extract_metrics(detail),
                checks=extract_checks(detail),
                raw=detail,
            )
        kind = str(alpha_type or "REGULAR").upper()
        body: dict[str, Any] = {}
        if not location:
            payload: dict[str, Any] = {"type": kind, "settings": dict(settings)}
            if kind == "REGULAR":
                payload["regular"] = expression
            else:
                payload["expression"] = expression
            try:
                response = self.client.request(
                    "POST",
                    f"{BASE_URL}/simulations",
                    json=payload,
                    endpoint_class="simulation_submit",
                    allow_server_retry=False,
                )
            except (requests.Timeout, requests.ConnectionError) as exc:
                raise SimulationOutcomeUnknown(
                    "simulation POST ended without a confirmable platform response"
                ) from exc
            if response.status_code not in {200, 201, 202}:
                raise PlatformReadError(f"simulation submit failed with HTTP {response.status_code}")
            try:
                parsed = response.json()
            except Exception:
                parsed = {}
            body = parsed if isinstance(parsed, dict) else {}
            alpha_id = str(alpha_id_from_progress(body) or "").strip()
            location = str(response.headers.get("Location") or "").strip()
            if not alpha_id and not location:
                raise SimulationOutcomeUnknown(
                    "accepted simulation response has no alpha id or progress location"
                )
